using System;
using System.Collections.Generic;
using System.Text;

namespace NESOOP.Compiler
{
    public sealed class Nes6502CodeGenerator
    {
        private const string ExpressionTemp =
            "__nesoop_expr_temp";


        public string Generate(
            SemanticProgram program
        )
        {
            StringBuilder output = new();


            output.AppendLine(
                "; =========================================================="
            );

            output.AppendLine(
                "; GENERATED BY NesOop.Compiler"
            );

            output.AppendLine(
                "; DO NOT EDIT MANUALLY"
            );

            output.AppendLine(
                "; =========================================================="
            );

            output.AppendLine();



            // =========================================================
            // RAM
            // =========================================================

            output.AppendLine(
                ".segment \"BSS\""
            );

            output.AppendLine();


            output.AppendLine(
                $"{ExpressionTemp}: .res 1"
            );


            foreach (
                SemanticByteDeclaration variable
                in program.Methods
                    .SelectMany(
                        method =>
                            method.Statements
                    )
                    .OfType<SemanticByteDeclaration>()
            )
            {
                output.AppendLine(
                    $"{variable.StorageName}: .res 1"
                );
            }


            output.AppendLine();



            // =========================================================
            // CODE
            // =========================================================

            output.AppendLine(
                ".segment \"CODE\""
            );

            output.AppendLine();


            // The handwritten NES runtime calls this.
            output.AppendLine(
                ".export Game_Start"
            );

            output.AppendLine();



            // =========================================================
            // Generate every method
            // =========================================================

            foreach (
                SemanticMethod method
                in program.Methods
            )
            {
                GenerateMethod(
                    output,
                    method
                );
            }


            return output.ToString();
        }



        private static void GenerateMethod(
            StringBuilder output,
            SemanticMethod method
        )
        {
            output.AppendLine(
                $"; ----------------------------------------------------------"
            );

            output.AppendLine(
                $"; {method.ClassName}.{method.Name}()"
            );

            output.AppendLine(
                $"; ----------------------------------------------------------"
            );


            output.AppendLine(
                $".proc {method.Label}"
            );

            output.AppendLine();


            foreach (
                SemanticStatement statement
                in method.Statements
            )
            {
                GenerateStatement(
                    output,
                    statement
                );
            }


            // Every void method returns using RTS.
            output.AppendLine(
                "    rts"
            );

            output.AppendLine();

            output.AppendLine(
                ".endproc"
            );

            output.AppendLine();
        }



        private static void GenerateStatement(
            StringBuilder output,
            SemanticStatement statement
        )
        {
            // =========================================================
            // Local byte
            // =========================================================

            if (
                statement
                is SemanticByteDeclaration variable
            )
            {
                output.AppendLine(
                    $"    ; byte {variable.Name}"
                );


                GenerateLoadValue(
                    output,
                    variable.Initializer
                );


                output.AppendLine(
                    $"    sta {variable.StorageName}"
                );

                output.AppendLine();

                return;
            }



            // =========================================================
            // Variable assignment
            // =========================================================

            if (
                statement
                is SemanticVariableAssignment assignment
            )
            {
                GenerateLoadValue(
                    output,
                    assignment.Value
                );


                output.AppendLine(
                    $"    sta {assignment.StorageName}"
                );

                output.AppendLine();

                return;
            }



            // =========================================================
            // Method call
            //
            // This is where:
            //
            // SetColor();
            //
            // becomes:
            //
            // JSR Game_SetColor
            // =========================================================

            if (
                statement
                is SemanticMethodCall call
            )
            {
                output.AppendLine(
                    $"    jsr {call.TargetLabel}"
                );

                output.AppendLine();

                return;
            }



            // =========================================================
            // Screen.BackgroundColor
            // =========================================================

            if (
                statement
                is SemanticBackgroundColorAssignment background
            )
            {
                output.AppendLine(
                    "    ; Screen.BackgroundColor"
                );


                output.AppendLine(
                    "    lda $2002"
                );

                output.AppendLine();


                output.AppendLine(
                    "    lda #$3F"
                );

                output.AppendLine(
                    "    sta $2006"
                );

                output.AppendLine();


                output.AppendLine(
                    "    lda #$00"
                );

                output.AppendLine(
                    "    sta $2006"
                );

                output.AppendLine();


                GenerateLoadValue(
                    output,
                    background.Value
                );


                output.AppendLine(
                    "    and #$3F"
                );


                output.AppendLine(
                    "    sta $2007"
                );

                output.AppendLine();

                return;
            }



            throw new Exception(
                "Internal compiler error: " +
                "unknown semantic statement."
            );
        }



        private static void GenerateLoadValue(
            StringBuilder output,
            SemanticValue value
        )
        {
            switch (value)
            {
                case SemanticByteLiteral literal:

                    output.AppendLine(
                        $"    lda #${literal.Value:X2}"
                    );

                    return;



                case SemanticVariableReference variable:

                    output.AppendLine(
                        $"    lda {variable.StorageName}"
                    );

                    return;



                case SemanticBinaryAdd add:

                    GenerateLoadValue(
                        output,
                        add.Left
                    );


                    output.AppendLine(
                        "    pha"
                    );


                    GenerateLoadValue(
                        output,
                        add.Right
                    );


                    output.AppendLine(
                        $"    sta {ExpressionTemp}"
                    );


                    output.AppendLine(
                        "    pla"
                    );


                    output.AppendLine(
                        "    clc"
                    );


                    output.AppendLine(
                        $"    adc {ExpressionTemp}"
                    );


                    return;



                default:

                    throw new Exception(
                        "Internal compiler error: " +
                        "cannot load semantic value."
                    );
            }
        }
    }
}
